    magnitude = Fraction(n, divisor ** unit_index)
    tenths = rounded_tenths(magnitude)

    while tenths >= divisor * 10 and unit_index < len(units) - 1:
        unit_index += 1
        magnitude = Fraction(n, divisor ** unit_index)
        tenths = rounded_tenths(magnitude)

    whole = tenths // 10
    frac = tenths % 10
    return sign + f"{whole}.{frac} {units[unit_index]}"


